import { randomUUID } from "node:crypto";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
  createIsolatedDatabase,
  databaseTestsEnabled,
} from "./helpers/foundation-db";

describe.runIf(databaseTestsEnabled)("Dodo test billing migration", () => {
  let fixture: Awaited<ReturnType<typeof createIsolatedDatabase>>;
  beforeAll(async () => {
    fixture = await createIsolatedDatabase();
    try {
      for (const name of fixture.migrations) await fixture.apply(name);
    } catch (error) {
      await fixture.cleanup();
      throw error;
    }
  });
  afterAll(async () => {
    if (fixture) await fixture.cleanup();
  });

  it("preserves existing billing rows during the additive completion migration and disables checkout", async () => {
    const upgrade = await createIsolatedDatabase();
    try {
      const completion = "20261020020000_dodo_billing_completion";
      for (const migration of upgrade.migrations) {
        if (migration === completion) break;
        await upgrade.apply(migration);
      }
      await upgrade.client.query(
        `INSERT INTO "BillingWebhookEvent" (id,"webhookId","eventType","businessId","occurredAt","normalizedData","payloadHash",state) VALUES ('receipt','wh_existing','payment.succeeded','business',now(),'{}',repeat('a',64),'PROCESSED')`,
      );
      await upgrade.client.query(
        `INSERT INTO "BillingSubscription" (id,"dodoSubscriptionId","dodoCustomerId","productId",status,"settledPaymentId","paymentConfirmedAt","periodStart","periodEnd","updatedAt") VALUES ('existing','sub_existing','cus_existing','pdt_existing','ACTIVE','pay_existing',now(),now()-interval '1 day',now()+interval '29 days',now())`,
      );
      const before = (
        await upgrade.client.query(`SELECT * FROM "BillingWebhookEvent"`)
      ).rows;
      await upgrade.apply(completion);
      expect(
        (await upgrade.client.query(`SELECT * FROM "BillingWebhookEvent"`))
          .rows,
      ).toEqual(before);
      expect(
        (
          await upgrade.client.query(
            `SELECT "billingCheckoutEnabled" FROM "SystemControl" WHERE key='global'`,
          )
        ).rows,
      ).toEqual([{ billingCheckoutEnabled: false }]);
      expect(
        (
          await upgrade.client.query(
            `SELECT "settledPaymentId","cancelRequestedAt" FROM "BillingSubscription" WHERE id='existing'`,
          )
        ).rows,
      ).toEqual([
        { settledPaymentId: "pay_existing", cancelRequestedAt: null },
      ]);
    } finally {
      await upgrade.cleanup();
    }
  });
  it("enforces UUID rate-limit IDs, owner and operation identity, and positive minute counts", async () => {
    const userId = randomUUID();
    await fixture.client.query(`INSERT INTO "User" (id,email) VALUES ($1,$2)`, [
      userId,
      userId + "@example.test",
    ]);
    const insert = (id: string, operation = "status", count = 1) =>
      fixture.client.query(
        `INSERT INTO "BillingRateLimit" (id,"userId",operation,"minuteBucket","requestCount") VALUES ($1,$2,$3,date_trunc('minute',now()),$4)`,
        [id, userId, operation, count],
      );
    await expect(insert("not-a-uuid")).rejects.toMatchObject({ code: "22P02" });
    await expect(
      insert(randomUUID(), "foreign-operation"),
    ).rejects.toMatchObject({ code: "23514" });
    await expect(insert(randomUUID(), "status", 0)).rejects.toMatchObject({
      code: "23514",
    });
    await insert(randomUUID());
    await expect(insert(randomUUID())).rejects.toMatchObject({ code: "23505" });
    await fixture.client.query(`DELETE FROM "User" WHERE id=$1`, [userId]);
    expect(
      (
        await fixture.client.query(
          `SELECT * FROM "BillingRateLimit" WHERE "userId"=$1`,
          [userId],
        )
      ).rows,
    ).toEqual([]);
  });

  it("retains subscription and checkout evidence when the owner is deleted", async () => {
    await fixture.client.query(
      `INSERT INTO "User" (id,email) VALUES ('owner','[REDACTED_EMAIL]')`,
    );
    await fixture.client.query(
      `INSERT INTO "BillingSubscription" (id,"userId","ownerIdSnapshot","dodoSubscriptionId","dodoCustomerId","productId",status,"updatedAt") VALUES ('sub','owner','owner','sub_test','cus_test','pdt_test','CANCELLED',now())`,
    );
    await fixture.client.query(
      `INSERT INTO "CheckoutAttempt" (id,"userId","ownerIdSnapshot","idempotencyKey","productId","billingCountry","expiresAt",status) VALUES ('attempt','owner','owner','key','pdt_test','IN',now()+interval '1 day','COMPLETED')`,
    );
    await fixture.client.query(`DELETE FROM "User" WHERE id='owner'`);
    for (const table of ["BillingSubscription", "CheckoutAttempt"]) {
      const result = await fixture.client.query(
        `SELECT "userId","ownerIdSnapshot" FROM "${table}"`,
      );
      expect(result.rows).toEqual([{ userId: null, ownerIdSnapshot: "owner" }]);
    }
  });

  it("enforces one unresolved checkout and paired provider binding", async () => {
    await fixture.client.query(
      `INSERT INTO "User" (id,email) VALUES ('concurrent','[REDACTED_EMAIL]')`,
    );
    const insert = (id: string) =>
      fixture.client.query(
        `INSERT INTO "CheckoutAttempt" (id,"userId","idempotencyKey","productId","billingCountry","expiresAt",status) VALUES ($1,'concurrent',$1,'pdt_test','IN',now()+interval '1 day','UNKNOWN')`,
        [id],
      );
    await insert("first");
    await expect(insert("second")).rejects.toMatchObject({
      code: "23505",
      constraint: "CheckoutAttempt_one_open_per_user",
    });
    await fixture.client.query(
      `UPDATE "SystemControl" SET "dodoEnvironment"='live_mode',"dodoBusinessId"='business' WHERE key='global'`,
    );
    await expect(
      fixture.client.query(
        `UPDATE "SystemControl" SET "dodoEnvironment"='other_mode' WHERE key='global'`,
      ),
    ).rejects.toMatchObject({ code: "23514" });
    await expect(
      fixture.client.query(
        `UPDATE "SystemControl" SET "dodoEnvironment"=NULL,"dodoBusinessId"='business' WHERE key='global'`,
      ),
    ).rejects.toMatchObject({ code: "23514" });
    await fixture.client.query(
      `UPDATE "SystemControl" SET "dodoEnvironment"='test_mode',"dodoBusinessId"='business' WHERE key='global'`,
    );
  });

  it("preserves a pre-existing checkout while allowing country to be collected later", async () => {
    const upgrade = await createIsolatedDatabase();
    try {
      const migration = "20261020010000_hosted_checkout_country";
      for (const name of upgrade.migrations) {
        if (name === migration) break;
        await upgrade.apply(name);
      }
      await upgrade.client.query(
        `INSERT INTO "CheckoutAttempt" (id,"idempotencyKey","productId","billingCountry","expiresAt",status,"dodoSessionId","checkoutUrl") VALUES ('existing','existing','pdt_test','IN',now()+interval '1 day','READY','cks_existing','https://test.checkout.dodopayments.com/session/existing')`,
      );
      const before = await upgrade.client.query(
        `SELECT * FROM "CheckoutAttempt" WHERE id='existing'`,
      );
      await upgrade.apply(migration);
      expect(
        (
          await upgrade.client.query(
            `SELECT * FROM "CheckoutAttempt" WHERE id='existing'`,
          )
        ).rows,
      ).toEqual(before.rows);
      expect(
        (
          await upgrade.client.query(
            `INSERT INTO "CheckoutAttempt" (id,"idempotencyKey","productId","expiresAt") VALUES ('hosted','hosted','pdt_test',now()+interval '1 day') RETURNING "billingCountry"`,
          )
        ).rows,
      ).toEqual([{ billingCountry: null }]);
    } finally {
      await upgrade.cleanup();
    }
  });
});
